-- Backfill high-confidence legacy Google Sheet track counts.
-- Source timestamps are JST. play_date is the reporting day that starts at
-- 09:00 JST (= 00:00 UTC) and ends at 08:59 JST the next day.
-- Only days with title evidence at both day boundaries and no title-evidence
-- gap longer than five minutes are seeded. Consecutive identical title/artist
-- samples are one play; only per-day per-track counts are persisted.
--
-- Compact payload:
--   days   = [day_id, play_date]
--   tracks = [track_id, title, artist]
--   play bytes = day_id, track_id, play_count (one byte each, hex encoded).

DROP TRIGGER IF EXISTS trg_preserve_legacy_sheet_track_history;

DELETE FROM sh_pages_track_history_read_model
WHERE row_key LIKE 'legacy-sheet|%'
  AND play_date>='2025-06-06'
  AND play_date<='2025-07-29';

WITH RECURSIVE
days AS (
  SELECT
    CAST(json_extract(value,'$[0]') AS INTEGER) AS day_id,
    json_extract(value,'$[1]') AS play_date
  FROM json_each('[[1,"2025-06-06"],[2,"2025-06-08"],[3,"2025-06-09"],[4,"2025-06-10"],[5,"2025-06-11"],[6,"2025-06-13"],[7,"2025-06-15"],[8,"2025-06-16"],[9,"2025-06-17"],[10,"2025-06-18"],[11,"2025-06-19"],[12,"2025-06-20"],[13,"2025-06-22"],[14,"2025-06-24"],[15,"2025-06-27"],[16,"2025-06-29"],[17,"2025-06-30"],[18,"2025-07-02"],[19,"2025-07-03"],[20,"2025-07-10"],[21,"2025-07-11"],[22,"2025-07-12"],[23,"2025-07-14"],[24,"2025-07-15"],[25,"2025-07-18"],[26,"2025-07-20"],[27,"2025-07-21"],[28,"2025-07-24"],[29,"2025-07-25"],[30,"2025-07-26"],[31,"2025-07-27"],[32,"2025-07-28"],[33,"2025-07-29"]]')
),
tracks AS (
  SELECT
    CAST(json_extract(value,'$[0]') AS INTEGER) AS track_id,
    json_extract(value,'$[1]') AS title,
    json_extract(value,'$[2]') AS artist
  FROM json_each('[[1,"19歳のガレット","櫻坂46"],[2,"Action - The End","Harsh Bakshi"],[3,"Actually...","乃木坂46"],[4,"Addiction","櫻坂46"],[5,"Anthem time","櫻坂46"],[6,"BAN","櫻坂46"],[7,"Buddies","櫻坂46"],[8,"CHOU","土生瑞穂"],[9,"Cool","櫻坂46"],[10,"day dreamer","yousti"],[11,"Dead end","櫻坂46"],[12,"Don’t cut in line!","櫻坂46"],[13,"Fake-Perfect","yousti"],[14,"I''m in","櫻坂46"],[15,"Interlude #1","櫻坂46"],[16,"Interlude #2","櫻坂46"],[17,"Interlude #3","櫻坂46"],[18,"Interlude #4","櫻坂46"],[19,"Interlude #5","櫻坂46"],[20,"Interlude #6","櫻坂46"],[21,"Interlude #7","櫻坂46"],[22,"I want tomorrow to come","櫻坂46"],[23,"I want tomorrow to come -Naeleck Remix-","櫻坂46"],[24,"Make or Break","櫻坂46"],[25,"My fans","日向坂46"],[26,"Nightmare症候群","櫻坂46"],[27,"Nobody''s fault","櫻坂46"],[28,"Nothing special","櫻坂46"],[29,"One-way stairs","櫻坂46"],[30,"On my way","櫻坂46"],[31,"Overture","櫻坂46"],[32,"Plastic regret","櫻坂46"],[33,"Start over!","櫻坂46"],[34,"TOKYO SNOW","櫻坂46"],[35,"UDAGAWA GENERATION","櫻坂46"],[36,"UDAGAWA GENERATION -TSAR Remix-","櫻坂46"],[37,"ULTRAVIOLET","櫻坂46"],[38,"ごめんねFingers crossed","乃木坂46"],[39,"ずっと 春だったらなあ","櫻坂46"],[40,"その日まで","櫻坂46"],[41,"ってか","日向坂46"],[42,"なぜ 恋をして来なかったんだろう?","櫻坂46"],[43,"ひつじのショーン","石井竜也"],[44,"もう一曲 欲しいのかい?","櫻坂46"],[45,"もしかしたら真実","櫻坂46"],[46,"もしも心が透明なら","乃木坂46"],[47,"やるしかないじゃん","櫻坂46"],[48,"イザベルについて","櫻坂46"],[49,"インフルエンサー","乃木坂46"],[50,"ガールズルール","乃木坂46"],[51,"ガラス窓が汚れてる","日向坂46"],[52,"コンセントレーション","欅坂46"],[53,"コンビナート","櫻坂46"],[54,"シンクロニシティ","乃木坂46"],[55,"ジャーマンアイリス","日向坂46"],[56,"ジャマイカビール","櫻坂46"],[57,"ソニア","櫻坂46"],[58,"タイムマシーンでYeah!","櫻坂46"],[59,"ドローン旋回中","櫻坂46"],[60,"ノンアルコール","櫻坂46"],[61,"ピッカーン!","Giga"],[62,"ブルームーンキス","櫻坂46"],[63,"マグカップとシンク","乃木坂46"],[64,"マモリビト","櫻坂46"],[65,"マンホールの蓋の上","櫻坂46"],[66,"一瞬の馬","櫻坂46"],[67,"主よ、人の望みの喜びよ (オリジナルアーティスト : バッハ)","Mobile Melody Series"],[68,"二人セゾン","欅坂46"],[69,"五月雨よ","櫻坂46"],[70,"今さらSuddenly","櫻坂46"],[71,"何度 LOVE SONGの歌詞を読み返しただろう","櫻坂46"],[72,"何歳の頃に戻りたいのか?","櫻坂46"],[73,"何歳の頃に戻りたいのか? | Ikutsunokoronimodoritainoka? -Raiden Remix-","櫻坂46"],[74,"偶然の答え","櫻坂46"],[75,"僕たちの La vie en rose","櫻坂46"],[76,"僕のジレンマ","櫻坂46"],[77,"僕は僕を好きになれない","櫻坂46"],[78,"制服の人魚","櫻坂46"],[79,"半信半疑","櫻坂46"],[80,"君がサヨナラ言えたって・・・","櫻坂46"],[81,"君のことを想いながら","櫻坂46"],[82,"夏の近道","櫻坂46"],[83,"夜明けまで強がらなくてもいい","乃木坂46"],[84,"嵐の前、世界の終わり","櫻坂46"],[85,"引きこもる時間はない","櫻坂46"],[86,"心の影絵","櫻坂46"],[87,"思ったよりも寂しくない","櫻坂46"],[88,"恋が絶滅する日","櫻坂46"],[89,"恋は向いてない","櫻坂46"],[90,"恋愛無双","櫻坂46"],[91,"愛し合いなさい","櫻坂46"],[92,"承認欲求","櫻坂46"],[93,"承認欲求 | Shoninyokkyu -Ninajirachi Remix-","櫻坂46"],[94,"拍手 (歓声入り)","コロムビア・スタジオ"],[95,"摩擦係数","櫻坂46"],[96,"断絶","櫻坂46"],[97,"最終の地下鉄に乗って","櫻坂46"],[98,"月と星が踊るMidnight","日向坂46"],[99,"期待していない自分","けやき坂46"],[100,"本質的なこと","櫻坂46"],[101,"条件反射で泣けて来る","櫻坂46"],[102,"桜月","櫻坂46"],[103,"標識","櫻坂46"],[104,"櫻坂の詩","櫻坂46"],[105,"死んだふり","櫻坂46"],[106,"油を注せ!","櫻坂46"],[107,"泣かせて Hold me tight!","櫻坂46"],[108,"流れ弾","櫻坂46"],[109,"港区パセリ","櫻坂46"],[110,"無念","櫻坂46"],[111,"無言の宇宙","櫻坂46"],[112,"真夏に何か起きるのかしら","櫻坂46"],[113,"真夏の大統領","櫻坂46"],[114,"砂塵","欅坂46"],[115,"確信的クロワッサン","櫻坂46"],[116,"紋白蝶が確か飛んでた","櫻坂46"],[117,"縁起担ぎ","櫻坂46"],[118,"美しきNervous","櫻坂46"],[119,"自業自得","櫻坂46"],[120,"自業自得 | Jigoujitoku -devin Remix-","櫻坂46"],[121,"行かないで","櫻坂46"],[122,"見たことない魔物","日向坂46"],[123,"設定温度","乃木坂46"],[124,"車間距離","櫻坂46"],[125,"隙間風よ","櫻坂46"],[126,"青いベンチ","サスケ"],[127,"静寂の暴力","櫻坂46"],[128,"静寂の暴力 | Seijyaku no bouryoku -NURKO Remix-","櫻坂46"],[129,"風の音","櫻坂46"],[130,"魂のLiar","櫻坂46"],[131,"黒い羊","欅坂46"]]')
),
packed(data) AS (
  VALUES('')
),
positions(pos) AS (
  SELECT 1
  UNION ALL
  SELECT pos+6 FROM positions,packed WHERE pos+6<=length(data)
),
plays AS (
  SELECT
    (instr('0123456789ABCDEF',substr(data,pos,1))-1)*16
      +(instr('0123456789ABCDEF',substr(data,pos+1,1))-1) AS day_id,
    (instr('0123456789ABCDEF',substr(data,pos+2,1))-1)*16
      +(instr('0123456789ABCDEF',substr(data,pos+3,1))-1) AS track_id,
    (instr('0123456789ABCDEF',substr(data,pos+4,1))-1)*16
      +(instr('0123456789ABCDEF',substr(data,pos+5,1))-1) AS play_count
  FROM positions,packed
),
resolved AS (
  SELECT days.play_date,tracks.track_id,tracks.title,tracks.artist,plays.play_count
  FROM plays
  JOIN days USING(day_id)
  JOIN tracks USING(track_id)
)
INSERT INTO sh_pages_track_history_read_model(
  row_key,play_date,first_played_at,row_json,updated_at
)
SELECT
  'legacy-sheet|' || resolved.play_date || '|' || resolved.track_id,
  resolved.play_date,
  NULL,
  json_object(
    'play_date',resolved.play_date,
    'track_key','legacy-sheet:' || resolved.track_id,
    'title',resolved.title,
    'artist',resolved.artist,
    'play_count',resolved.play_count,
    'period_complete',json('true'),
    'play_count_excluded',json('false'),
    'exclusion_reasons',json('[]'),
    'source','legacy_google_sheet'
  ),
  1790208000000
FROM resolved
WHERE NOT EXISTS (
  SELECT 1
  FROM sh_pages_track_history_read_model existing
  WHERE existing.play_date=resolved.play_date
    AND existing.row_key NOT LIKE 'legacy-sheet|%'
)
ON CONFLICT(row_key) DO UPDATE SET
  play_date=excluded.play_date,
  first_played_at=excluded.first_played_at,
  row_json=excluded.row_json,
  updated_at=excluded.updated_at;

-- Runtime track-history refreshes can revisit these dates. Preserve the
-- spreadsheet-derived rows unless a later migration explicitly drops the guard.
DROP TRIGGER IF EXISTS trg_preserve_legacy_sheet_track_history;
CREATE TRIGGER trg_preserve_legacy_sheet_track_history
BEFORE DELETE ON sh_pages_track_history_read_model
WHEN OLD.row_key LIKE 'legacy-sheet|%'
BEGIN
  SELECT RAISE(IGNORE);
END;
